@MainActor
final class PushManager: NSObject, UNUserNotificationCenterDelegate {
    func register() async throws {
        let center = UNUserNotificationCenter.current()
        center.delegate = self
        if try await center.requestAuthorization(options: [.alert, .badge, .sound]) {
            UIApplication.shared.registerForRemoteNotifications()
        }
    }

    // Foreground: still show the banner
    func userNotificationCenter(_ c: UNUserNotificationCenter, willPresent n: UNNotification) async
        -> UNNotificationPresentationOptions { [.banner, .sound] }

    // User tapped
    func userNotificationCenter(_ c: UNUserNotificationCenter, didReceive r: UNNotificationResponse) async {
        if let link = r.notification.request.content.userInfo["deeplink"] as? String,
           let url = URL(string: link) { Router.shared.handle(url) }
    }
}

// AppDelegate
func application(_ app: UIApplication, didRegisterForRemoteNotificationsWithDeviceToken token: Data) {
    let hex = token.map { String(format: "%02x", $0) }.joined()
    Task { try await api.uploadPushToken(hex) }
}
